    const age = Date.now() - (stat.mtime?.getTime() ?? 0);
    if (age < 24 * 60 * 60 * 1000) {
      const cached = await Deno.readTextFile(cachePath);
      return JSON.parse(cached) as OpenAPISpec;
    }
  } catch {
    // Cache miss — proceed to fetch
