const SWAMP_READ_NAMES = new Set([
  "get",
  "read",
  "describe",
  "show",
  "list",
  "search",
  "find",
]);

/**
 * True when some resource of the model declares a sensitive field, which is
 * what makes swamp demand a vault before it runs the model's methods.
 */
export function modelRequiresVault(methods: ClassifiedMethod[]): boolean {
  return [...planSecrets(methods).methods.values()].some((e) =>
    e.vaulted.length > 0
  );
}

/** The sentence stating which of a model's methods need a vault to exist. */
