/**
 * The cache name carries the pinned SHA: the bytes at a commit never change,
 * so a cached copy needs no expiry, and a copy left by another pin is never
 * read.
export async function fetchSchema(
  cacheDir?: string,
): Promise<OpenAPISpec> {
  const dir = cacheDir ?? CACHE_DIR;
  const cachePath = join(dir, CACHE_FILE);

  // Try cache first
  try {
    const cached = await Deno.readTextFile(cachePath);
    console.log(`   Using cached spec: ${cachePath}`);
    return parseYaml(cached) as unknown as OpenAPISpec;
  } catch {
    // Cache miss — proceed to fetch
  }

  console.log(
    `   Fetching Datadog v2 OpenAPI spec from GitHub at ${SCHEMA_SHA}...`,
  );
  const response = await fetch(SCHEMA_URL);
  if (!response.ok) {
    throw new Error(
      `Failed to fetch schema: ${response.status} ${response.statusText}`,
    );
  }

  const text = await response.text();

  // Write raw YAML to cache
  await Deno.mkdir(dir, { recursive: true });
