import re
COMMON = '''/** Lowercase-hex SHA-256 of the spec text, as `sha256sum` prints it. */
export async function sha256Hex(text: string): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(text),
  );
  return Array.from(
    new Uint8Array(digest),
    (b) => b.toString(16).padStart(2, "0"),
  ).join("");
}

/**
 * Fetch the spec text at `url` and verify it against `expected`. A `null`
 * expectation skips the check, for a re-pin that is establishing the hash.
 */
export async function fetchSpecText(
  url: string = SCHEMA_URL,
  expected: string | null = SPEC_SHA256,
): Promise<{ text: string; hash: string }> {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(
      `Failed to fetch schema: ${response.status} ${response.statusText}`,
    );
  }
  const text = await response.text();
  const hash = await sha256Hex(text);
  if (expected !== null && hash !== expected) {
    throw new Error(
      `__NAME__ spec hash mismatch at ${url}.\\n` +
        `  expected: ${expected}\\n  fetched:  ${hash}\\n` +
        `The pinned commit should never change; check SCHEMA_SHA and ` +
        `SPEC_SHA256 in config.ts.`,
    );
  }
  return { text, hash };
}

/**
 * Load the pinned spec. A cached copy is used only when its hash matches
 * SPEC_SHA256, so a truncated or foreign file is fetched again; the cache is
 * written through a temporary file and renamed into place.
 */
export async function fetchSchema(
  cacheDir?: string,
): Promise<OpenAPISpec> {
  const dir = cacheDir ?? CACHE_DIR;
  const cachePath = join(dir, CACHE_FILE);

