  console.log(`   Fetching __NAME__ OpenAPI spec at ${SCHEMA_SHA}...`);
  const { text } = await fetchSpecText();
  await Deno.mkdir(dir, { recursive: true });
  const tmp = `${cachePath}.${crypto.randomUUID()}.tmp`;
  await Deno.writeTextFile(tmp, text);
  await Deno.rename(tmp, cachePath);
  console.log(`   Cached spec to ${cachePath} (${text.length} bytes)`);
  return __PARSE__(text);
}
