/**
 * Fetch the live spec and, when it differs from the pin, re-vendor it and
 * rewrite SPEC_SHA256. Returns whether the pin moved.
 */
async function updateSpec(dryRun: boolean): Promise<boolean> {
  console.log(`📥 Fetching the live fal.ai OpenAPI spec...`);
  const { bytes, hash } = await fetchLiveSpec();
  if (hash === SPEC_SHA256) {
    console.log(`   ✓ Unchanged. Pin already at ${hash}.`);
    return false;
  }
  console.log(`   old pin: ${SPEC_SHA256}`);
  console.log(`   new pin: ${hash}`);
  if (dryRun) {
    console.log(`   [DRY RUN] would re-vendor the spec and re-pin config.ts`);
    return false;
  }
  const config = await Deno.readTextFile(CONFIG_PATH);
  const updated = config.replace(
    /export const SPEC_SHA256 =\s*\n?\s*"[0-9a-f]{64}";/,
    `export const SPEC_SHA256 =\n  "${hash}";`,
  );
  if (updated === config) {
    throw new Error(
      `Could not find the SPEC_SHA256 literal to rewrite in config.ts. ` +
        `Nothing was changed.`,
    );
  }
  await writeVendoredSpec(bytes);
  await Deno.writeTextFile(CONFIG_PATH, updated);
  console.log(`   ✓ Re-vendored the spec and re-pinned SPEC_SHA256.`);
  return true;
}

