export interface PinSnapshot {
  path: string;
  bytes: Uint8Array<ArrayBuffer>;
}

/**
 * Run the regeneration that follows a re-pin. When it fails before writing
 * anything, put the snapshotted pin files back; when it fails after the write
 * pass began (EXIT_AFTER_WRITES), keep the new pin, since the rewritten
 * extensions came from it. Returns the regeneration's exit code.
 */
export async function rerunWithRollback(
  snapshot: PinSnapshot[],
  run: () => Promise<number>,
): Promise<number> {
  const code = await run();
  if (code === EXIT_AFTER_WRITES) {
    console.error(
      `\\n⚠️  Regeneration failed after writing some extensions; the new pin ` +
        `stays. Review git status, then rerun or revert.`,
    );
  } else if (code !== 0) {
    for (const { path, bytes } of snapshot) await Deno.writeFile(path, bytes);
    console.error(`\\n↩️  Regeneration failed; restored the previous pin.`);
  }
  return code;
}

